## 📡 ESP32 (Arduino) Kodu

Bu kod, ESP32 kartının Wi-Fi ağına bağlanmasını, HTTP GET isteği ile sunucudan ışık durumunu sorgulamasını ve bu duruma göre dahili LED'i (GPIO 2) kontrol etmesini sağlar. **`WiFi.h`**, **`HTTPClient.h`** ve **`ArduinoJson.h`** kütüphaneleri gereklidir.

```cpp
#include <WiFi.h>
#include <HTTPClient.h>
#include <ArduinoJson.h>

const char* ssid = "SSID";         // Wi-Fi Ağ Adı (Değiştirin)
const char* password = "PASSWORD"; // Wi-Fi Şifresi (Değiştirin)
const String url = "[https://keremkk-isik.glitch.me/isikdurumu](https://keremkk-isik.glitch.me/isikdurumu)"; // Sunucu Durum URL'si

void setup() {

    Serial.begin(115200);

    // LED Pini Tanımlama: ESP32'de genellikle dahili LED GPIO 2'ye bağlıdır.
    pinMode(2, OUTPUT);

    // Wi-Fi Bağlantısı
    WiFi.begin(ssid, password);

    Serial.print("Wi-Fi'a bağlanılıyor");
    while (WiFi.status() != WL_CONNECTED) {
        delay(500);
        Serial.print(".");
    }

    Serial.println("\nWi-Fi bağlantısı başarılı!");
}

void loop() {

    if (WiFi.status() == WL_CONNECTED) {    // Sadece bağlıyken çalıştır

        HTTPClient http;
        http.begin(url);

        int httpCode = http.GET(); // GET isteği at

        if (httpCode == 200) {      // Başarılı yanıt (HTTP OK)

            String payload = http.getString();
            Serial.println("Sunucu Yanıtı: " + payload);

            // JSON ayrıştırma
            DynamicJsonDocument doc(1024);
            DeserializationError error = deserializeJson(doc, payload);

            if (!error) {
                bool durum = doc["durum"]; // Sunucudan gelen durumu al

                Serial.print("LED Durumu: ");
                Serial.println(durum ? "Açık" : "Kapalı");

                // LED'i kontrol et (GPIO 2)
                digitalWrite(2, durum); 
            } else {
                 Serial.println("JSON Ayrıştırma Hatası!");
            }
        } else {
             Serial.print("HTTP Hatası: ");
             Serial.println(httpCode);
        }

        http.end(); // HTTP bağlantısını kapat
    } else {
         Serial.println("Wi-Fi bağlantısı kesildi!");
    }

    delay(500); // 500 ms bekleyerek sunucuyu periyodik kontrol et
}
```

